test_setup_files.behavior_test.js:
const assert = require('assert');
const { dedupeBy } = require('./build/dedupe.js');
const input = [
  { id: 1, v: 'first-1' },
  { id: 2, v: 'first-2' },
  { id: 1, v: 'second-1' },
  { id: 3, v: 'first-3' },
  { id: 2, v: 'second-2' },
];
const snapshot = JSON.stringify(input);
const out = dedupeBy(input, (r) => r.id);
assert.deepStrictEqual(out.map((r) => r.v), ['first-1', 'first-2', 'first-3'],
  'must keep FIRST occurrence per key, in order');
assert.strictEqual(JSON.stringify(input), snapshot, 'input must not be mutated');
assert.deepStrictEqual(dedupeBy([], (x) => x), []);
console.log('PASS');

reference_solution.dedupe.ts:
export function dedupeBy<T, K>(items: T[], key: (item: T) => K): T[] {
  const seen = new Set<K>();
  const out: T[] = [];
  for (const item of items) {
    const k = key(item);
    if (!seen.has(k)) {
      seen.add(k);
      out.push(item);
    }
  }
  return out;
}

